// Read the user-configured values from Set upload inputs.
// Use a new ID for a new document; retain the same ID for retries.
const input = $input.first().json;

const filePath = input.filePath.trim();
const fileName = input.fileName.trim();
const sourceDocumentId = input.sourceDocumentId.trim();
const missing = [
  !filePath && 'filePath (absolute file path on the n8n server)',
  !fileName && 'fileName (filename ending in .pdf)',
  !sourceDocumentId && 'sourceDocumentId (stable ID from your source system)',
].filter(Boolean);
if (missing.length) {
  throw new Error('Before uploading, fill in these fields in Set upload inputs: ' + missing.join(', ') + '. No API request was sent.');
}
if ([filePath, fileName, sourceDocumentId].some(value => /BITTE_|HIER_EINTRAGEN|YOUR_|<[^>]*>/i.test(value))) {
  throw new Error('Replace all placeholders in Set upload inputs. No API request was sent.');
}
if (!(/^(?:\/|[A-Za-z]:[\\/])/.test(filePath)) || /[*?\[\]{}]/.test(filePath)) {
  throw new Error('filePath must be an absolute server path to exactly one file, without wildcard patterns.');
}
if (!/\.pdf$/i.test(fileName) || /[\\/\x00-\x1f]/.test(fileName)) {
  throw new Error('fileName must be a single PDF filename without a directory path.');
}
if (!/^[!-~]{1,128}$/.test(sourceDocumentId)) {
  throw new Error('sourceDocumentId must contain 1 to 128 printable ASCII characters without spaces. Keep this ID unchanged for retries.');
}

return [{json: {
  baseUrl: 'https://app.bimetrics.de',
  filePath,
  fileName,
  sourceDocumentId,
  uploadRequestId: sourceDocumentId,
  maxStatusRequests: 6,
  pollIntervalSeconds: 5,
}}];

const items = $input.all();
if (items.length !== 1 || !items[0].binary?.data) {
  throw new Error('Expected exactly one PDF as binary data in the data field. Check the file path on the n8n server.');
}
const cfg = $('Validate upload inputs').first().json;
return [{json: cfg, binary: {data: {
  ...items[0].binary.data,
  fileName: cfg.fileName,
  mimeType: 'application/pdf',
}}}];

const response = $input.first().json;
const status = Number(response.statusCode);
if (!(status >= 200 && status < 300)) {
  const code = typeof response.body?.code === 'string' ? response.body.code : 'UnknownAPIError';
  const retryAfter = response.headers?.['retry-after'] ?? null;
  const instruction = status === 429
    ? 'Wait for the number of seconds in Retry-After. Retry only with the same company, key, upload ID, file, filename and field.'
    : status >= 500
      ? 'Temporary server error. Retry with bounded attempts and increasing delays; keep the entire upload identity unchanged.'
      : 'Check the request, key, permissions and plan. No automatic retry.';
  throw new Error(JSON.stringify({phase: 'upload', httpStatus: status, code, retryAfter, instruction}));
}
if (!Array.isArray(response.body) || response.body.length !== 1 || typeof response.body[0].id !== 'string' || !response.body[0].id) {
  throw new Error('The upload response does not contain exactly one document with a document ID. Inspect the response before retrying the upload.');
}
const document = response.body[0];
return [{json: {
  documentId: document.id,
  uploadStatus: document.uploadDocument?.ocrStatus ?? null,
  duplicate: document.duplicate === true,
  uploadRequestId: $('Validate upload inputs').first().json.uploadRequestId,
}}];

const first = $('Read upload response').first().json;
const response = $input.first().json;
const status = Number(response.statusCode);
if (!(status >= 200 && status < 300)) {
  const code = typeof response.body?.code === 'string' ? response.body.code : 'UnknownAPIError';
  const retryAfter = response.headers?.['retry-after'] ?? null;
  const instruction = status === 429
    ? 'Wait for the number of seconds in Retry-After, then read this document ID again. No new upload is needed.'
    : status >= 500
      ? 'Read the status of this document ID again later with increasing delays. No new upload is needed.'
      : 'The upload already returned a document ID. Check the key and read permission; use this ID for further status requests.';
  throw new Error(JSON.stringify({phase: 'read-status', documentId: first.documentId, httpStatus: status, code, retryAfter, instruction}));
}
if (response.body?.id !== first.documentId) {
  throw new Error('The status response contains an unexpected document ID.');
}
const cfg = $('Validate upload inputs').first().json;
const statusValue = response.body.uploadDocument?.ocrStatus;
if (!['pending', 'processing', 'success', 'failed', 'quota_paused'].includes(statusValue)) {
  throw new Error('The API returned an unknown processing status. Keep the document ID from Read upload response and inspect the response.');
}
const statusRequests = $runIndex + 1;
const shouldPoll = ['pending', 'processing'].includes(statusValue) && statusRequests < cfg.maxStatusRequests;
const outcome = statusValue === 'success' ? 'processed'
  : statusValue === 'failed' ? 'processing_failed'
  : statusValue === 'quota_paused' ? 'quota_paused'
  : shouldPoll ? 'pending' : 'poll_limit_reached';
const nextAction = outcome === 'processed'
  ? 'The API reports that processing is complete. Open the document in bimetrics and review its data; this status is not approval of a booking.'
  : outcome === 'quota_paused'
    ? 'Check the document allowance and this stored document. Do not upload the file again under a new ID.'
    : outcome === 'processing_failed'
      ? 'Open this stored document in bimetrics and inspect the processing error. Do not upload it again under a new ID.'
      : outcome === 'poll_limit_reached'
        ? 'Processing is still pending. Keep the document ID and read its status again later; do not upload it again.'
        : 'Wait five seconds before the next status request.';
return [{json: {...first, ocrStatus: statusValue, statusRequests, shouldPoll, outcome, nextAction}}];
